INSERT INTO kb.ingredient_allergens (ingredient_id, allergen_group_id, certainty, source, note)
SELECT i.ingredient_id,
       ag.allergen_group_id,
       m.certainty,
       m.source,
       m.note
  FROM mapping_data m
  JOIN kb.ingredients     i  ON i.slug = m.slug
  JOIN kb.allergen_groups ag ON ag.code = m.allergen_code
ON CONFLICT (ingredient_id, allergen_group_id) DO UPDATE
SET certainty = EXCLUDED.certainty,
    source    = EXCLUDED.source,
    note      = EXCLUDED.note;
